.ds-drafting { --ds-cover-bg: var(--ds-vellum); background-image: linear-gradient(var(--ds-grid) 1px, transparent 1px), linear-gradient(90deg, var(--ds-grid) 1px, transparent 1px); background-size: 24px 24px; }
.ds-drafting .ds-section h2, .ds-drafting .ds-cover-name { font-family: var(--font-display); text-transform: uppercase; }
.ds-drafting .ds-chip { border-radius: 0; font-family: "Archivo Narrow", sans-serif; }
.ds-drafting .ds-comp, .ds-drafting .ds-motif, .ds-drafting .ds-note, .ds-drafting .ds-voice, .ds-drafting .ds-code { border-color: var(--ds-ink); }
.ds-drafting .d-paper { fill: var(--ds-vellum); } .ds-drafting .d-grid { stroke: var(--ds-grid); stroke-width: 1; } .ds-drafting .d-frame { fill: none; stroke: var(--ds-ink); stroke-width: 1; }
.ds-drafting .d-ink2 { fill: none; stroke: var(--ds-ink); stroke-width: 2; } .ds-drafting .d-ink1 { fill: none; stroke: var(--ds-ink); stroke-width: 1; } .ds-drafting .d-block { fill: var(--ds-vellum-raised); stroke: var(--ds-ink); stroke-width: 1; }
.ds-drafting .d-dim { stroke: var(--ds-cobalt); stroke-width: 1; } .ds-drafting .d-ext { stroke: var(--ds-cobalt); stroke-width: 1; stroke-dasharray: 3 3; } .ds-drafting .d-arrow { fill: var(--ds-cobalt); } .ds-drafting .d-lead { stroke: var(--ds-vermilion); stroke-width: 1; }
.ds-drafting .d-dim-t { font-family: var(--font-mono); font-size: 12px; font-weight: 500; fill: var(--ds-cobalt); } .ds-drafting .d-blk-t { font-family: "Archivo Narrow", sans-serif; font-size: 11px; font-weight: 700; letter-spacing: .1em; fill: var(--ds-ink); }
.ds-drafting .d-rev { fill: var(--ds-vermilion-soft); stroke: var(--ds-vermilion); stroke-width: 1.5; } .ds-drafting .d-rev-t { font-family: "Archivo Narrow", sans-serif; font-size: 11px; font-weight: 700; letter-spacing: .1em; fill: var(--ds-vermilion); } .ds-drafting .d-rev-l { stroke: var(--ds-vermilion); stroke-width: 1; stroke-dasharray: 4 3; }
.ds-drafting .d-muted { color: var(--ds-ink-muted); } .ds-drafting .d-vermilion { color: var(--ds-vermilion); } .ds-drafting .d-ok { color: var(--ds-positive); }
.ds-drafting .d-btn { font-family: "Archivo Narrow", sans-serif; font-size: 13px; font-weight: 700; letter-spacing: .1em; text-transform: uppercase; line-height: 18px; padding: 10px 16px; border: 1px solid var(--ds-ink); background: var(--ds-vellum-raised); color: var(--ds-ink); cursor: pointer; transition: border-color 120ms, color 120ms; }
.ds-drafting .d-btn:hover { border-color: var(--ds-cobalt); color: var(--ds-cobalt); } .ds-drafting .d-btn:focus-visible { outline: 2px solid var(--ds-cobalt); outline-offset: 2px; }
.ds-drafting .d-btn-primary { background: var(--ds-cobalt); color: var(--ds-on-cobalt); border-color: var(--ds-cobalt); } .ds-drafting .d-btn-primary:hover { color: var(--ds-on-cobalt); border-color: var(--ds-ink); }
.ds-drafting .d-btn-rev { background: var(--ds-vermilion); color: var(--ds-on-vermilion); border-color: var(--ds-vermilion); } .ds-drafting .d-btn-rev:hover { color: var(--ds-on-vermilion); border-color: var(--ds-ink); }
.ds-drafting .d-tag { display: inline-flex; padding: 3px 8px; border: 1px solid var(--ds-ink); font-family: "Archivo Narrow", sans-serif; font-size: 11px; font-weight: 700; letter-spacing: .12em; text-transform: uppercase; background: var(--ds-vellum-raised); color: var(--ds-ink); }
.ds-drafting .d-tag-ok { color: var(--ds-positive); border-color: var(--ds-positive); background: var(--ds-positive-soft); } .ds-drafting .d-tag-assume { color: var(--ds-caution); border-color: var(--ds-caution); background: var(--ds-caution-soft); } .ds-drafting .d-tag-rev { color: var(--ds-vermilion); border-color: var(--ds-vermilion); background: var(--ds-vermilion-soft); }
.ds-drafting .d-stat { display: grid; gap: 6px; padding: 16px 20px; border: 1px solid var(--ds-ink); background: var(--ds-vellum-raised); min-width: 160px; } .ds-drafting .d-stat + .d-stat { border-left: 0; }
.ds-drafting .ds-stats { gap: 0; } .ds-drafting .d-stat-row { display: flex; flex-wrap: wrap; margin-top: 28px; } .ds-drafting .d-note { font-size: 12px; color: var(--ds-ink-muted); font-family: var(--font-mono); }
.ds-drafting .d-note-box { padding: 12px 14px; border: 1px solid var(--ds-ink); border-left-width: 4px; font-size: 14px; line-height: 1.5; background: var(--ds-vellum-raised); }
.ds-drafting .d-note-info { border-left-color: var(--ds-cobalt); } .ds-drafting .d-note-assume { border-left-color: var(--ds-caution); background: var(--ds-caution-soft); } .ds-drafting .d-note-rev { border-left-color: var(--ds-vermilion); background: var(--ds-vermilion-soft); }
.ds-drafting .d-sheet { border: 1px solid var(--ds-ink); background: var(--ds-vellum-raised); display: grid; transition: border-color 120ms; } .ds-drafting .d-sheet:hover { border-color: var(--ds-cobalt); }
.ds-drafting .d-sheet-body { padding: 20px 24px; } .ds-drafting .d-sheet h3 { margin: 6px 0 0; } .ds-drafting .d-sheet-p { margin: 10px 0 0; line-height: 1.55; color: var(--ds-ink-muted); max-width: 56ch; }
.ds-drafting .d-titleblock { display: flex; flex-wrap: wrap; border-top: 1px solid var(--ds-ink); } .ds-drafting .d-titleblock span { padding: 8px 12px; border-right: 1px solid var(--ds-ink); font-family: "Archivo Narrow", sans-serif; font-size: 11px; letter-spacing: .1em; text-transform: uppercase; flex: 1 1 auto; } .ds-drafting .d-titleblock span:last-child { border-right: 0; } .ds-drafting .d-titleblock b { color: var(--ds-ink-muted); margin-right: 6px; font-weight: 700; }
.ds-drafting .d-sample { padding: 40px 20px 64px; } .ds-drafting .d-sample-in { max-width: 1100px; margin: 0 auto; }
.ds-drafting .d-sample-sheet { border: 1px solid var(--ds-ink); background: var(--ds-vellum-raised); background-image: linear-gradient(var(--ds-grid) 1px, transparent 1px), linear-gradient(90deg, var(--ds-grid) 1px, transparent 1px); background-size: 24px 24px; }
.ds-drafting .d-sample-top { display: flex; justify-content: space-between; flex-wrap: wrap; gap: 8px; padding: 12px 24px; border-bottom: 1px solid var(--ds-ink); }
.ds-drafting .d-sample-grid { display: grid; gap: 24px; padding: 24px; } .ds-drafting .d-sample-h { margin: 0; max-width: 12ch; } .ds-drafting .d-sample-lede { margin-top: 20px; max-width: 48ch; }
.ds-drafting .d-sample-fig svg { display: block; width: 100%; max-width: 400px; height: auto; margin: 0 auto; } .ds-drafting .d-sample-bottom { padding: 0 24px 24px; }
@container (min-width: 760px) { .ds-drafting .d-sample { padding: 56px 40px 80px; } .ds-drafting .d-sample-grid { grid-template-columns: 3fr 2fr; padding: 48px 24px 24px; } }

.ds-drafting { --ds-hand-ink: var(--ds-ink); --ds-hand-fill: var(--ds-cobalt); --ds-hand-fill2: var(--ds-vermilion); --ds-hand-muted: var(--ds-vellum-sunk); --ds-hand-ground: var(--ds-vellum-raised); --ds-hand-stroke: 1.5; --ds-hand-cap: square; --ds-hand-bg: var(--ds-vellum);
  --ds-tpl-edge: 1px solid var(--ds-ink); --ds-tpl-radius: 0; --ds-tpl-rule: 1px solid var(--ds-ink); --ds-tag-radius: 0; --ds-slide-bg: var(--ds-vellum-raised); --ds-slide-title-bg: var(--ds-cobalt); --ds-slide-title-fg: var(--ds-on-cobalt); --ds-slide-split-a: var(--ds-cobalt); --ds-slide-split-b: var(--ds-vermilion); --ds-slide-split-b-fg: var(--ds-on-vermilion); --ds-hero-bg: var(--ds-vellum-raised); }
.ds-drafting .ds-hand-art, .ds-drafting .ds-tpl-figure { background-image: linear-gradient(var(--ds-grid) 1px, transparent 1px), linear-gradient(90deg, var(--ds-grid) 1px, transparent 1px); background-size: 24px 24px; }
.ds-drafting .h-ink { stroke-linejoin: miter; } .ds-drafting .h-outline-fill { stroke-width: 1.5; }
.ds-drafting .h-num { font-family: var(--font-mono); font-weight: 500; letter-spacing: -.02em; } .ds-drafting .h-text { font-family: "Archivo Narrow", sans-serif; font-size: 11px; font-weight: 700; letter-spacing: .1em; }
.ds-drafting .ds-tpl-tag { font-family: "Archivo Narrow", sans-serif; letter-spacing: .12em; border: 1px solid var(--ds-ink); background: var(--ds-vellum-raised); }
.ds-drafting .ds-tpl-tag.is-ok { border-color: var(--ds-positive); } .ds-drafting .ds-tpl-tag.is-warn { border-color: var(--ds-caution); } .ds-drafting .ds-tpl-tag.is-bad { border-color: var(--ds-vermilion); color: var(--ds-vermilion); background: var(--ds-vermilion-soft); }
.ds-drafting .ds-tpl-brand, .ds-drafting .ds-tpl-slide-h, .ds-drafting .ds-tpl-hero-h, .ds-drafting .ds-tpl-ed-h { text-transform: uppercase; }
.ds-drafting .ds-tpl-stage-top, .ds-drafting .ds-tpl-stage-foot { font-family: "Archivo Narrow", sans-serif; font-weight: 700; }
.ds-drafting .ds-tpl-kpi, .ds-drafting .ds-tpl-tile, .ds-drafting .ds-tpl-step { background: var(--ds-vellum-raised); }
.ds-drafting .ds-tpl-dropcap { color: var(--ds-cobalt); } .ds-drafting .ds-tpl-pull { border-top-color: var(--ds-cobalt); }

.ds-drafting .h-fill.h-outline-fill { fill: var(--ds-cobalt-soft); stroke: var(--ds-cobalt); stroke-width: 3.5; }
.ds-drafting .h-fill2.h-outline-fill { fill: var(--ds-vermilion-soft); stroke: var(--ds-vermilion); stroke-width: 3.5; }

.ds-drafting .ds-tpl-tile { overflow-x: auto; }
